package com.joysistvi.CyberAccess.service;
import com.joysistvi.CyberAccess.model.Order; import com.joysistvi.CyberAccess.repo.*; import java.sql.SQLException; import java.math.BigDecimal; import java.util.List;
public class OrderServiceImpl { private final OrderRepo repo; public OrderServiceImpl(){this(new OrderRepoImpl());} public OrderServiceImpl(OrderRepo r){repo=r;}
 public List<Order> getAll()throws SQLException{return repo.findAll();} public List<Order> getByUser(int id)throws SQLException{return repo.findByUser(Validation.id(id));} public Order getById(int id)throws SQLException{return repo.findById(Validation.id(id)).orElse(null);} public void create(Order x)throws SQLException{if(x==null)throw new IllegalArgumentException("Order is required.");Validation.id(x.getUserId());if(x.getAmount()==null)x.setAmount(BigDecimal.ZERO);Validation.decimal(x.getAmount(),"Amount",false);if(x.getStatus()==null||x.getStatus().isBlank())x.setStatus("Pending");repo.save(x);} public boolean update(Order x)throws SQLException{if(x==null)throw new IllegalArgumentException("Order is required.");Validation.id(x.getOrderId());Validation.id(x.getUserId());Validation.decimal(x.getAmount(),"Amount",false);Validation.text(x.getStatus(),"Status",30);return repo.update(x);} public boolean setStatus(int id,String status)throws SQLException{return repo.setStatus(Validation.id(id),Validation.text(status,"Status",30));} public boolean delete(int id)throws SQLException{return repo.delete(Validation.id(id));}}
